-- ===== VIEW VW_BASE2_VS_INCOMING_REPORT =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_BASE2_VS_INCOMING_REPORT" ("SER_NUMBER", "BUSS_DATE", "INS_CODE", "TXN_TYPE", "STATUS", "BASEII_COUNT", "BASEII_AMOUNT", "BASEII_IRF_AMOUNT", "INCOMING_COUNT", "INCOMING_AMOUNT", "INCOMING_IRF_AMOUNT", "TOTAL_COUNT", "TOTAL_AMOUNT", "TOTAL_IRF_AMOUNT", "CYCLE") AS 
  SELECT ROW_NUMBER() OVER (ORDER BY BUSS_DATE, INS_CODE, TXN_TYPE, STATUS ) AS SER_NUMBER,
BUSS_DATE, INS_CODE, TXN_TYPE, STATUS , SUM(BASEII_COUNT) BASEII_COUNT, SUM(BASEII_AMOUNT) BASEII_AMOUNT, 
SUM(BASEII_IRF_AMOUNT) BASEII_IRF_AMOUNT, SUM(INCOMING_COUNT) INCOMING_COUNT, SUM(INCOMING_AMOUNT) INCOMING_AMOUNT,
SUM(INCOMING_IRF_AMOUNT) INCOMING_IRF_AMOUNT, SUM(TOTAL_COUNT) TOTAL_COUNT, SUM(TOTAL_AMOUNT) TOTAL_AMOUNT, 
SUM(TOTAL_IRF_AMOUNT) TOTAL_IRF_AMOUNT, NULL CYCLE

from (WITH BASEII_DATA AS (
    SELECT 
        PTR.PTR_BUSS_DATE AS BUSS_DATE,
        PTR.PTR_INS_CODE  AS INS_CODE,
        VTD.VTD_TERMINAL_ID AS TERMINAL_ID,
        CASE 
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND trim(PTR.PTR_PROC_CODE) = '000000' THEN 'Sale'
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
        END AS TXN_TYPE,
        COUNT(DISTINCT VTD.VTD_SER_NUMBER) AS BASEII_COUNT,
        SUM(VTD.VTD_TXN_AMOUNT) AS BASEII_AMOUNT,
        SUM(PTR.PTR_IRF_AMOUNT) AS BASEII_IRF_AMOUNT
    FROM POS_TRANSACTIONS PTR
    JOIN VISA_ACQ_TXN_DATA VTD 
          ON VTD.VTD_RET_REF_NUMBER = PTR.PTR_RET_REF_NUMBER
    WHERE (PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE IN ('000000', '200000'))
    GROUP BY PTR.PTR_BUSS_DATE,
             PTR.PTR_INS_CODE,
             VTD.VTD_TERMINAL_ID ,
             CASE 
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND trim(PTR.PTR_PROC_CODE) = '000000' THEN 'Sale'
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
             END
),
INCOMING_DATA AS (
    SELECT 
         PTR.PTR_BUSS_DATE AS BUSS_DATE,
        PTR.PTR_INS_CODE  AS INS_CODE,
        VND.VND_TERMINAL_ID AS TERMINAL_ID,
        CASE 
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '000000' THEN 'Sale'
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
        END AS TXN_TYPE,
        COUNT(DISTINCT VND.VND_SER_NUMBER) AS INCOMING_COUNT,
        SUM(COALESCE(VND.VND_TXN_AMOUNT,0)) AS INCOMING_AMOUNT,
        SUM(COALESCE(VND.VND_INCHG_FEE_AMOUNT,0)) AS INCOMING_IRF_AMOUNT
    FROM POS_TRANSACTIONS PTR
    JOIN VISA_NETWORK_DATA VND 
         ON VND.VND_TERMINAL_ID = PTR.PTR_TERMINAL_ID
        AND VND.VND_TXN_ID      = PTR.PTR_TXN_ID
    WHERE (PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE IN ('000000', '200000'))
    GROUP BY PTR.PTR_BUSS_DATE,
             PTR.PTR_INS_CODE,
             VND.VND_TERMINAL_ID,
             CASE 
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '000000' THEN 'Sale'
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
             END
)
SELECT 
    COALESCE(I.BUSS_DATE, N.BUSS_DATE)         AS BUSS_DATE,
    COALESCE(I.INS_CODE, N.INS_CODE)           AS INS_CODE,
    COALESCE(I.TXN_TYPE, N.TXN_TYPE)           AS TXN_TYPE,
    COALESCE(I.BASEII_COUNT,0)                    AS BASEII_COUNT,
    COALESCE(I.BASEII_AMOUNT,0)                   AS BASEII_AMOUNT,
    COALESCE(I.BASEII_IRF_AMOUNT,0)               AS BASEII_IRF_AMOUNT,
    COALESCE(N.INCOMING_COUNT,0)               AS INCOMING_COUNT,
    COALESCE(N.INCOMING_AMOUNT,0)              AS INCOMING_AMOUNT,
    COALESCE(N.INCOMING_IRF_AMOUNT,0)          AS INCOMING_IRF_AMOUNT,
    (COALESCE(I.BASEII_COUNT,0) + COALESCE(N.INCOMING_COUNT,0)) AS TOTAL_COUNT,
    (COALESCE(I.BASEII_AMOUNT,0) + COALESCE(N.INCOMING_AMOUNT,0)) AS TOTAL_AMOUNT,
    (COALESCE(I.BASEII_IRF_AMOUNT,0) + COALESCE(N.INCOMING_IRF_AMOUNT,0)) AS TOTAL_IRF_AMOUNT,
    CASE 
        WHEN COALESCE(I.BASEII_COUNT,0)      <> COALESCE(N.INCOMING_COUNT,0)
          OR COALESCE(I.BASEII_AMOUNT,0)     <> COALESCE(N.INCOMING_AMOUNT,0)
          OR COALESCE(I.BASEII_IRF_AMOUNT,0) <> COALESCE(N.INCOMING_IRF_AMOUNT,0)
        THEN 'Unmatched'
        ELSE 'Matched'
    END AS STATUS,
    NULL AS CYCLE
FROM BASEII_DATA I
FULL OUTER JOIN INCOMING_DATA N
       ON I.BUSS_DATE   = N.BUSS_DATE
      AND I.INS_CODE    = N.INS_CODE
      AND I.TERMINAL_ID = N.TERMINAL_ID
      AND I.TXN_TYPE    = N.TXN_TYPE)
      GROUP BY BUSS_DATE,INS_CODE, TXN_TYPE, STATUS     
      ORDER BY BUSS_DATE ASC;
/

