  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_FILE_FORMATS" ("FOR_DESCRIPTION", "UPL_FILE_NAME", "UPL_BUSS_DATE", "UPL_TOT_ACCP_TXN_COUNT", "UPL_TOT_TXN_COUNT", "UPL_UPLOAD_STATUS", "UPL_REMARKS") AS 
