	TO_CHAR(MGW_LOCAL_DATE_TIME, 'YYMMDD') || REPLACE(TO_CHAR(MGW_LOCAL_DATE_TIME, 'HH24MISS'), ':', '') AS DE012, -- DE012
	NULL 				 AS DE014, 									--DE014
	MGW_POS_DATA_MODE 	 AS DE022,									--DE022
	NULL 				 AS DE023, 									--DE023
	MGW_FUNC_CODE 		 AS DE024, 									--DE024
	MGW_MSG_REASON_CODE  AS DE025, 									--DE025 
	MGW_MCC 			 AS DE026, 									--DE026
	NULL 				 AS DE030,									--DE030
	LPAD(NVL(MGW_ACQ_REF_DATA, '0'), 23, '0') AS DE031, 			--DE031	
	MGW_ACQ_INST_ID_CODE AS DE032, 									--DE032
	MGW_ACQ_INST_ID_CODE AS DE033, 									--DE033
	MGW_RET_REF_NUMBER 	 AS DE037, 									--DE037 
	RPAD(MGW_APPR_CODE, 6, ' ') AS DE038,						    --DE038
