	MGW_MERCHANT_ID 	 AS DE042,									--DE042	
	SUBSTR(MGW_ME_NAME, 1, 22) || '\' ||    						  --'
	SUBSTR(MGW_ME_ADDRESS, 1,45) || '\' ||        						  --'
