	SUBSTR(SUBSTR(MGW_ME_ZIP_CODE, 1, 10) || RPAD(' ', 10), 1, 10) ||
	MGW_ME_COUNTRY || MGW_ME_COUNTRY 		  AS DE043,  			--DE043		
	MGW_TXN_CUR_CODE 				  		  AS DE049,				--DE049 				
	NULL 							  		  AS DE054, 			--DE054 
	MGW_TXN_LIFE_CYCL_ID 			  		  AS DE063, 			--DE063
	LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY MGW_SER_NUMBER ASC) + 1), 8, '0') AS DE071, --DE071
	NULL AS DE072, 													--DE072
	NULL AS DE093, 													--DE093
