	NULL AS DE095, 													--DE095
	'0023003POI' AS DE048_0023, 									--DE048_0023 --PDS23
	'' AS DE048_0025, 												--DE048_0025 --PDS25
	'' AS DE048_0052, 												--DE048_0052 --PDS52
