	'0165001' || MGW_SETL_INDICATOR AS DE048_0165, 					--DE048_0165 --PDS165
	'' AS DE048_0176, 												--DE048_0176 --PDS176
	'' AS DE048_0211, 												--DE048_0211 --PDS211
	'' AS DE048_0262, 												--DE048_0262 --PDS262
	'' AS DE055_9F26, 												--DE055_9F26
	'' AS DE055_9F27, 												--DE055_9F27
	'' AS DE055_9F10, 												--DE055_9F10
	'' AS DE055_9F37, 												--DE055_9F37
	'' AS DE055_9F36, 												--DE055_9F36
	'' AS DE055_95, 												--DE055_95
