	'' AS DE055_9C, 												--DE055_9C				 
	'' AS DE055_9F02, 												--DE055_9F02
	'' AS DE055_5F2A, 												--DE055_5F2A
	'' AS DE055_82, 												--DE055_82
	'' AS DE055_9F1A, 												--DE055_9F1A
	'' AS DE055_9F03,  												--DE055_9F03
	'' AS DE055_9F34,												--DE055_9F34
	'' AS DE055_9F33,												--DE055_9F33
	'' AS DE055_84,													--DE055_84,
	MGW_LOCAL_DATE_TIME AS test,
	MGW_TXN_TYPE AS test1,
    MGW_TXN_AMOUNT AS test2
FROM MC_GCO_WORK  
WHERE MGW_GEN_STATUS =9;
/

-- ===== VIEW VW_INTERFACE =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_INTERFACE" ("INT_NAME", "FOR_DESCRIPTION", "UPL_FILE_NAME", "PRJ_START_TIME", "PRJ_END_TIME", "UPL_TOT_TXN_COUNT", "UPL_TOT_ACCP_TXN_COUNT", "UPL_UPLOAD_STATUS", "UPL_BUSS_DATE", "UPL_PROC_DATE") AS 
  SELECT INT_NAME,FOR_DESCRIPTION,UPL_FILE_NAME,PRJ_START_TIME,PRJ_END_TIME,UPL_TOT_TXN_COUNT,UPL_TOT_ACCP_TXN_COUNT,
UPL_UPLOAD_STATUS,UPL_BUSS_DATE,UPL_PROC_DATE FROM FILE_UPLOAD_LOG JOIN INTERFACES ON UPL_INT_CODE=INT_CODE JOIN FILE_FORMATS 
ON FOR_CODE=UPL_FOR_CODE JOIN PROCESSING_JOBS ON PRJ_SER_NUMBER=UPL_PRJ_SER_NUMBER;
/

-- ===== VIEW VW_IPM_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_IPM_DETAILS" ("IIC_IRD", "IIC_SER_NUMBER", "IIC_RATE_PERCENT", "IIC_RATE_FIXED", "MIP_SER_NUMBER", "IIC_PRIORITY", "IIC_MIN_AMOUNT", "IIC_MAX_AMOUNT") AS 
  SELECT
	IIC_IRD,
	IIC_SER_NUMBER,
	IIC_RATE_PERCENT,
	IIC_RATE_FIXED,MIP_SER_NUMBER,IIC_PRIORITY,IIC_MIN_AMOUNT,IIC_MAX_AMOUNT FROM IPM_IRD_CODES
			JOIN IPM_CARD_PROG ON IIC_SER_NUMBER = ICP_IIC_SER_NUMBER
			JOIN IPM_GCMS_PROD_ID ON IIC_SER_NUMBER = IGP_IIC_SER_NUMBER
				JOIN IPM_CAB_PROGRAMS ON IIC_SER_NUMBER = CAB_IIC_SER_NUMBER
                JOIN MC_IRF_PARAMS ON MIP_INS_CODE = 1
			WHERE
				 IIC_PROG_REGION = MIP_PROG_REGION
				AND IIC_TIMELINE >= MIP_TIMELINE
				AND IIC_MIN_AMOUNT <= MIP_TXN_AMOUNT
				AND IIC_MAX_AMOUNT >= MIP_TXN_AMOUNT
				AND IIC_APPR_CODE IN (0,MIP_APPR_CODE_FLAG)
				AND IIC_MAGSTRIPE_DATA IN (0,MIP_MAGSTRIPE_FLAG)
				AND IIC_TRACE_ID IN (0,MIP_TRACE_ID_FLAG)
				AND IIC_MC_ASSIGNED_ID IN (0,MIP_MC_ASSIG_ID_FLAG)
				AND ICP_CARD_PROG_ID = MIP_CARD_PROG_ID AND ICP_ISSUER_REGION = MIP_ISSUER_REGION
				AND IGP_GCMS_PROD_ID = MIP_GCMS_PROD_ID AND IGP_ISSUER_REGION = MIP_ISSUER_REGION
				AND CAB_CAB_PROG IN  (SELECT MCL_CAB_PROGRAM FROM IPM_MCC_CAB_LIST WHERE MCL_ME_CATEGORY = MIP_MCC)
				AND 0 = (SELECT COUNT(1) FROM IPM_EXCLUDED_MCC WHERE IEM_IIC_SER_NUMBER=IIC_SER_NUMBER AND IEM_EXCP_MCC = MIP_MCC)
				AND IIC_PROC_CODE = (SELECT COUNT(1) FROM IPM_PROC_CODES WHERE IPC_IIC_SER_NUMBER=IIC_SER_NUMBER AND IPC_PROC_CODE=MIP_TXN_TYPE)
				AND IIC_POS_DATA_1 = (select COUNT(1) from IPM_POS_DATA_1 WHERE ID1_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID1_POS_DATA_1 = MIP_CARD_INPUT_ABILITY)
				AND IIC_POS_DATA_3 = (select COUNT(1) from IPM_POS_DATA_3 WHERE ID3_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID3_POS_DATA_3 = MIP_CARD_CAPTURE_ABILITY)
				AND IIC_POS_DATA_4 = (select COUNT(1) from IPM_POS_DATA_4 WHERE ID4_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID4_POS_DATA_4 = MIP_OPRT_ENVIRONMENT)
				AND IIC_POS_DATA_5 = (select COUNT(1) from IPM_POS_DATA_5 WHERE ID5_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID5_POS_DATA_5 = MIP_CH_PRESENT)
				AND IIC_POS_DATA_6 = (select COUNT(1) from IPM_POS_DATA_6 WHERE ID6_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID6_POS_DATA_6 = MIP_CARD_PRESENT)
				AND IIC_POS_DATA_7 = (select COUNT(1) from IPM_POS_DATA_7 WHERE ID7_IIC_SER_NUMBER = IIC_SER_NUMBER AND ID7_POS_DATA_7 = MIP_CARD_INPUT_MODE)
				AND IIC_SERV_CODE = (select COUNT(1) from IPM_SERVICE_CODES WHERE ISC_IIC_SER_NUMBER = IIC_SER_NUMBER AND ISC_SERV_CODE = SUBSTR(MIP_SERVICE_CODE,0,1))
				AND IIC_ECOM_INDICATOR = (SELECT COUNT(1) FROM IPM_ECOM_INDICATOR WHERE IEI_IIC_SER_NUMBER = IIC_SER_NUMBER AND IEI_ECOM_INDICATOR= MIP_ECOM_INDICATOR)
				AND IIC_F40_22_RELATION = (SELECT COUNT(1) FROM IPM_40_22_RELATION WHERE IIR_IIC_SER_NUMBER=IIC_SER_NUMBER AND IIR_SERV_CODE_1 = SUBSTR(MIP_SERVICE_CODE,0,1) AND IIR_POS_DATA_1=MIP_CARD_INPUT_ABILITY)
			ORDER BY IIC_PRIORITY;
/

-- ===== VIEW VW_IPM_OUT_WORK =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_IPM_OUT_WORK" ("SERIALNO", "DE001", "DE002", "DE003", "DE004", "DE012", "DE014", "DE022", "DE023", "DE024", "DE025", "DE026", "DE030", "DE031", "DE033", "DE037", "DE038", "DE040", "DE041", "DE042", "DE043", "DE049", "DE054", "DE063", "DE071", "DE072", "DE093", "DE095", "DE048_0023_PDS23", "DE048_0025", "DE048_0052", "DE048_0137", "DE048_0148", "DE048_0149", "DE048_0155", "DE048_0165", "DE048_0176", "DE048_0211", "DE048_0262", "DE055_9F26", "DE055_9F27", "DE055_9F10", "DE055_9F37", "DE055_9F36", "DE055_95", "DE055_9A", "DE055_9C", "DE055_9F02", "DE055_5F2A", "DE055_82", "DE055_9F1A", "DE055_9F03", "TEST", "TEST1", "TEST2", "DE048_PDS0213", "DE055_9F34", "DE055_9F33", "DE055_84", "DE048_0170", "DE048_0018", "DE048_0175") AS 
  SELECT   
    MCT_SER_NUMBER AS SERIALNO, 
    NVL(MCT_MSG_TYPE_ID, '') AS DE001,  -- DE001      
    MCT_ENC_CARD_NUMBER AS DE002, -- DE002
    MCT_PROC_CODE AS DE003, -- DE003
	CASE 
		WHEN MCT_DCC_INDICATOR = 'Y' THEN
			LPAD(TO_CHAR(ROUND((MCT_DCC_AMOUNT * POWER(10, MCT_DCC_CURR_EXP)) + (MCT_SCHG_AMOUNT * POWER(10, MCT_DCC_CURR_EXP)))),12,'0')
		ELSE
			LPAD(TO_CHAR(ROUND((MCT_TXN_AMOUNT * POWER(10, MCT_TXN_CURR_EXP)) + (MCT_SCHG_AMOUNT * POWER(10, MCT_TXN_CURR_EXP)))),12,'0')
    END AS DE004, --DE004
	-- DCC Amount = DCC Amount × 10^ Currency Exponent of dcc country; Other Amount = Amount × 10^Currency Exponent of actual country.

    TO_CHAR(MCT_LOCAL_DATE_TIME, 'YYMMDD') || REPLACE(TO_CHAR(MCT_LOCAL_DATE_TIME, 'HH24MISS'), ':', '') AS DE012, -- DE012
    MCT_EXPIRY_DATE AS DE014, -- DE014
    MCT_POS_DATA_CODE AS DE022, -- DE022
    MCT_CARD_SEQ_NUMBER AS DE023, -- DE023
    MCT_FUNC_CODE AS DE024, -- DE024
    MCT_MSG_REASON_CODE AS DE025, -- DE025 
    MCT_MCC AS DE026, -- DE026
    CASE 
        WHEN MCT_FUNC_CODE IN ('205', '282') THEN 
            LPAD(TO_CHAR(TO_NUMBER(MRP_ORG_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0') || RPAD('0', 12, '0')
        ELSE NULL 
    END AS DE030, -- DE030
    LPAD(NVL(MCT_ACQ_REF_DATA, '0'), 23, '0') AS DE031, -- DE031
    MCT_ACQ_INST_ID_CODE AS DE033, -- DE033
    MCT_RET_REF_NUMBER AS DE037, -- DE037
    RPAD(MCT_APPR_CODE, 6, ' ') AS DE038, -- DE038
    MCT_SERVICE_CODE AS DE040, -- DE040
    MCT_TERMINAL_ID AS DE041, -- DE041
    MCT_MERCHANT_ID AS DE042, -- DE042
	SUBSTR(MCT_ME_NAME, 1, 22) || '\' ||                                   --'
	SUBSTR(MCT_CARD_ACC_STREET_ADDRESS, 1, 45) || '\' ||                  --'
	SUBSTR(SUBSTR(MCT_ME_CITY, 1, 13) || RPAD(' ', 13), 1, 13) || '\' ||  --'
	SUBSTR(SUBSTR(MCT_ME_ZIP_CODE, 1, 10) || RPAD(' ', 10), 1, 10) ||
	MCT_ME_COUNTRY || MCT_ME_COUNTRY   AS DE043,  -- DE043

	CASE WHEN MCT_DCC_INDICATOR = 'Y' THEN
        MCT_DCC_CURRENCY
    ELSE
        MCT_TXN_CUR_CODE END AS DE049, -- DE049

	CASE 
		WHEN NVL(MCT_CASHBACK_AMOUNT, 0) > 0 
			 OR NVL(MCT_TIP_AMOUNT, 0) > 0 
			 OR MCT_DCC_INDICATOR = 'Y' 
		THEN
			-- Occurrence 1: Cashback (Type 40)
			CASE WHEN NVL(MCT_CASHBACK_AMOUNT, 0) > 0 THEN 
				'0040' || MCT_TXN_CUR_CODE || 'D' || LPAD(TO_CHAR(TRUNC(MCT_CASHBACK_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0')
			ELSE '' END ||

			-- Occurrence 2: Tip (Type 44)
			CASE WHEN NVL(MCT_TIP_AMOUNT, 0) > 0 THEN 
				'0044' || MCT_TXN_CUR_CODE || 'D' || LPAD(TO_CHAR(TRUNC(MCT_TIP_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0')
			ELSE '' END ||

			-- Occurrence 3: DCC / POI Amount (Type 58)
			CASE WHEN MCT_DCC_INDICATOR = 'Y' THEN
				'0058' || MCT_TXN_CUR_CODE || 'D' || LPAD(TO_CHAR(TRUNC(MCT_TXN_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0')
			ELSE '' END
		ELSE NULL 
	END AS DE054, --DE054

    MCT_TXN_LIFE_CYCL_ID AS DE063, -- DE063
    LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY MCT_SER_NUMBER ASC) + 1), 8, '0') AS DE071, -- DE071
    NULL AS DE072, -- DE072
    CASE 
        WHEN MCT_MSG_TYPE_ID = '1740' THEN MCT_ORG_INST_ID_CODE 
        ELSE NULL 
    END AS DE093, -- DE093
    CASE 
        WHEN MCT_FUNC_CODE IN ('205', '282') THEN 
            LPAD(NVL(MRP_ISS_REF_NUMBER, '0'), 10, '0') 
        ELSE NULL 
    END AS DE095, -- DE095
    '0023003' || MCT_TRL_TYPE AS DE048_0023_PDS23, -- DE048_0023 -- PDS23
    CASE 
        WHEN MCT_REV_INDICATOR = 'R' THEN '0025007R' || TO_CHAR(MCT_CENTRE_PROC_DATE, 'YYYYMMDD') 
        ELSE '' 
    END AS DE048_0025, -- DE048_0025 -- PDS25
    CASE 
        WHEN MCT_ECOM_INDICATOR IS NULL THEN '' 
        ELSE '0052003' || MCT_ECOM_INDICATOR 
    END AS DE048_0052, -- DE048_0052 -- PDS52
    '0137017' || LPAD(NVL(MCT_ACQ_REF_DATA, '0'), 17, '0') AS DE048_0137, -- DE048_0137 -- PDS137
   --  '0148004' || MCT_TXN_CUR_CODE || TO_CHAR(MCT_TXN_CURR_EXP) AS DE048_0148, -- DE048_0148 -- PDS148

    CASE 
        WHEN MCT_DCC_INDICATOR = 'Y' AND MCT_DCC_CURRENCY IS NOT NULL THEN
            '0148008' || MCT_TXN_CUR_CODE || TO_CHAR(MCT_TXN_CURR_EXP) || 
                         MCT_DCC_CURRENCY || TO_CHAR(MCT_DCC_CURR_EXP)
        ELSE
            '0148004' || MCT_TXN_CUR_CODE || TO_CHAR(MCT_TXN_CURR_EXP)
    END AS DE048_0148, -- DE048_0148 -- PDS148

    CASE 
        WHEN MCT_FUNC_CODE IN ('205', '282') THEN '0149006' || NVL(MCT_TXN_CUR_CODE, '') || '000' 
        ELSE '' 
    END AS DE048_0149, -- DE048_0149 -- PDS149
    '0158012' || RPAD(' ', 10) || MCT_IRD AS DE048_0155, -- DE048_0155 -- PDS155
    '0165001' || MCT_SETL_INDICATOR AS DE048_0165, -- DE048_0165 -- PDS165
    CASE 
        WHEN MCT_MER_MC_ASSIGNED_ID IS NULL THEN '' 
        ELSE '0176006' || MCT_MER_MC_ASSIGNED_ID 
    END AS DE048_0176, -- DE048_0176 -- PDS176
    CASE 
        WHEN MCT_ECOM_INDICATOR IS NULL THEN '021100222' 
        ELSE '' 
    END AS DE048_0211, -- DE048_0211 -- PDS211
    CASE 
        WHEN MCT_FUNC_CODE IN ('205', '282') THEN '0262001' || NVL(MRP_DOC_INDICATOR, '0') 
        ELSE '' 
    END AS DE048_0262, -- DE048_0262 -- PDS262
    CASE 
        WHEN MCT_APP_CRYPTOGRAM IS NULL THEN '' 
        ELSE '9F2608' || MCT_APP_CRYPTOGRAM 
    END AS DE055_9F26, -- DE055_9F26
    CASE 
        WHEN MCT_CRYPT_INFO_DATA IS NULL THEN '' 
        ELSE '9F2701' || MCT_CRYPT_INFO_DATA 
    END AS DE055_9F27, -- DE055_9F27
    MCT_ISS_APP_DATA AS DE055_9F10, -- DE055_9F10
    CASE 
        WHEN MCT_UPBL_NUMBER IS NULL THEN '' 
        ELSE '9F3704' || MCT_UPBL_NUMBER 
    END AS DE055_9F37, -- DE055_9F37
    CASE 
        WHEN MCT_APP_TXN_COUNTER IS NULL THEN '' 
        ELSE '9F3602' || MCT_APP_TXN_COUNTER 
    END AS DE055_9F36, -- DE055_9F36
    CASE 
        WHEN MCT_TRL_VER_RESULTS IS NULL THEN '' 
        ELSE '9505' || MCT_TRL_VER_RESULTS 
    END AS DE055_95, -- DE055_95
   /* CASE 
        WHEN MCT_CHIP_TXN_DATE IS NULL THEN '' 
        ELSE '9A03' || TO_CHAR(MCT_CHIP_TXN_DATE, 'YYYYMMDD') 
    END AS DE055_9A, -- DE055_9A*/
	CASE WHEN MCT_CHIP_TXN_DATE IS NULL THEN '' 
        ELSE '9A03'|| MCT_CHIP_TXN_DATE END AS DE055_9A, --DE055_9A
    CASE 
        WHEN MCT_CHIP_TXN_TYPE IS NULL THEN '' 
        ELSE '9C01' || MCT_CHIP_TXN_TYPE 
    END AS DE055_9C, -- DE055_9C
    CASE 
        WHEN MCT_CRYPT_AMOUNT IS NULL THEN '' 
        ELSE '9F0206' || LPAD(TO_CHAR(TRUNC(MCT_CRYPT_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0')
    END AS DE055_9F02, -- DE055_9F02
    CASE 
        WHEN MCT_CHIP_CUR_CODE IS NULL THEN '' 
        ELSE '5F2A02' || LPAD(MCT_CHIP_CUR_CODE, 4, '0')
    END AS DE055_5F2A, -- DE055_5F2A
    CASE 
        WHEN MCT_APP_IC_PROFILE IS NULL THEN '' 
        ELSE '8202' || MCT_APP_IC_PROFILE 
    END AS DE055_82, -- DE055_82
    CASE 
        WHEN MCT_TRL_CON_CODE IS NULL THEN '' 
        ELSE '9F1A02' || LPAD(MCT_TRL_CON_CODE, 4, '0')
    END AS DE055_9F1A, -- DE055_9F1A
    CASE 
        WHEN MCT_APP_CRYPTOGRAM IS NULL OR NVL(MCT_CASHBACK_AMOUNT, 0) = 0 THEN '' 
        ELSE '9F0306' || LPAD(TO_CHAR(TRUNC(MCT_CASHBACK_AMOUNT * POWER(10, MCT_TXN_CURR_EXP))), 12, '0')
    END AS DE055_9F03,
    MCT_LOCAL_DATE_TIME AS test,
    MCT_TXN_TYPE AS test1,
    MCT_TXN_AMOUNT AS test2,
	CASE 
        WHEN MCT_ME_COUNTRY_OF_ORIGIN IS NULL THEN '' 
        ELSE '0213003'||MCT_ME_COUNTRY_OF_ORIGIN
    END AS DE048_PDS0213, -- DE048_PDS0213,
	CASE WHEN MCT_CVM_RESULTS IS NULL THEN '' 
        ELSE '9F34' || '03' || MCT_CVM_RESULTS END AS DE055_9F34,-- DE055_9F34
    CASE WHEN MCT_CHIP_TRL_CAPABILITIES IS NULL THEN '' 
        ELSE '9F33' || '03' || MCT_CHIP_TRL_CAPABILITIES END AS DE055_9F33,-- DE055_9F33	
	MCT_DEDICATED_FILE_NAME AS DE055_84,-- DE055_84

	CASE
		WHEN  MCT_CUSTOMER_SERVICE_PHONE_NO IS NULL 
		THEN NULL

		WHEN MCT_ME_COUNTRY IN ('USA', 'CAN')
			 AND REGEXP_LIKE(REPLACE(MCT_CUSTOMER_SERVICE_PHONE_NO, '+', ''),'^[0-9]+$')
		THEN
			'0170016' || RPAD(MCT_CUSTOMER_SERVICE_PHONE_NO, 16, ' ')

		WHEN MCT_ME_COUNTRY NOT IN ('USA', 'CAN')
			-- AND REGEXP_LIKE(MCT_CUSTOMER_SERVICE_PHONE_NO, '^[0-9]{10}$')
			 AND LENGTH(MCT_CUSTOMER_SERVICE_PHONE_NO) BETWEEN 5 AND 15
		THEN
			'0170016' || RPAD(MCT_CUSTOMER_SERVICE_PHONE_NO, 16, ' ')

		ELSE NULL
	END AS DE048_0170, -- DE048_0170 -- PDS170
	CASE
		WHEN MCT_MPOS_ACC_DEV_TYPE IS NOT NULL
			THEN '0018001' || MCT_MPOS_ACC_DEV_TYPE
		ELSE NULL
    END AS DE048_0018, -- DE048_0018 --PDS0018

	CASE
		WHEN SUBSTR(MCT_POS_DATA_CODE, 7, 1) IN ('7', 'S', 'R', 'T')
			 AND TRIM(MCT_ACC_URL_ADDRESS) IS NOT NULL
		THEN
			'0175'
			|| LPAD(LENGTH(TRIM(MCT_ACC_URL_ADDRESS)), 3, '0')
			|| TRIM(MCT_ACC_URL_ADDRESS) 
		ELSE
			NULL
	END AS DE048_0175 -- DE048_0175 -- PDS175

FROM MC_ACQ_TXN_WORK
LEFT JOIN MC_REPR_GENERATED 
    ON MCT_MRP_SER_NUMBER = MRP_SER_NUMBER 
    AND MCT_FUNC_CODE IN ('205', '282')
WHERE MCT_GEN_STATUS = 9;
/

-- ===== VIEW VW_IPM_VS_INCOMING_REPORT =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_IPM_VS_INCOMING_REPORT" ("SER_NUMBER", "BUSS_DATE", "INS_CODE", "TXN_TYPE", "STATUS", "IPM_COUNT", "IPM_AMOUNT", "IPM_IRF_AMOUNT", "INCOMING_COUNT", "INCOMING_AMOUNT", "INCOMING_IRF_AMOUNT", "TOTAL_COUNT", "TOTAL_AMOUNT", "TOTAL_IRF_AMOUNT", "CYCLE") AS 
  SELECT ROW_NUMBER() OVER (ORDER BY BUSS_DATE, INS_CODE, TXN_TYPE, STATUS ) AS SER_NUMBER,
BUSS_DATE, INS_CODE, TXN_TYPE, STATUS , SUM(IPM_COUNT) IPM_COUNT, SUM(IPM_AMOUNT) IPM_AMOUNT, 
SUM(IPM_IRF_AMOUNT) IPM_IRF_AMOUNT, SUM(INCOMING_COUNT) INCOMING_COUNT, SUM(INCOMING_AMOUNT) INCOMING_AMOUNT,
SUM(INCOMING_IRF_AMOUNT) INCOMING_IRF_AMOUNT, SUM(TOTAL_COUNT) TOTAL_COUNT, SUM(TOTAL_AMOUNT) TOTAL_AMOUNT, 
SUM(TOTAL_IRF_AMOUNT) TOTAL_IRF_AMOUNT, NULL CYCLE

from (WITH IPM_DATA AS (
    SELECT 
        PTR.PTR_BUSS_DATE AS BUSS_DATE,
        PTR.PTR_INS_CODE  AS INS_CODE,
        MCT.MCT_TERMINAL_ID AS TERMINAL_ID,
        CASE 
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND trim(PTR.PTR_PROC_CODE) = '000000' THEN 'Sale'
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
        END AS TXN_TYPE,
        COUNT(DISTINCT MCT.MCT_SER_NUMBER) AS IPM_COUNT,
        SUM(MCT.MCT_TXN_AMOUNT)            AS IPM_AMOUNT,
        SUM(PTR.PTR_IRF_AMOUNT)            AS IPM_IRF_AMOUNT
    FROM POS_TRANSACTIONS PTR
    JOIN MC_ACQ_TXN_DATA MCT 
         ON MCT.MCT_RET_REF_NUMBER = PTR.PTR_RET_REF_NUMBER
    WHERE (PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE IN ('000000', '200000'))
    GROUP BY PTR.PTR_BUSS_DATE,
             PTR.PTR_INS_CODE,
            MCT.MCT_TERMINAL_ID,
             CASE 
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND trim(PTR.PTR_PROC_CODE) = '000000' THEN 'Sale'
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
             END
),
INCOMING_DATA AS (
    SELECT 
        PTR.PTR_BUSS_DATE AS BUSS_DATE,
        PTR.PTR_INS_CODE  AS INS_CODE,
        MND.MND_TERMINAL_ID AS TERMINAL_ID,
        CASE 
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '000000' THEN 'Sale'
            WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
        END AS TXN_TYPE,
        COUNT(DISTINCT MND.MND_SER_NUMBER)              AS INCOMING_COUNT,
        SUM(COALESCE(MND.MND_RECON_AMOUNT,0))           AS INCOMING_AMOUNT,
        SUM(COALESCE(MND.MND_TXN_IRF_AMOUNT,0))         AS INCOMING_IRF_AMOUNT
    FROM POS_TRANSACTIONS PTR
    JOIN MC_NETWORK_DATA MND 
         ON MND.MND_TERMINAL_ID = PTR.PTR_TERMINAL_ID
        AND MND.MND_TRACE_ID    = PTR.PTR_NETWORK_DATA
    WHERE (PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE IN ('000000', '200000'))
    GROUP BY PTR.PTR_BUSS_DATE,
             PTR.PTR_INS_CODE,
             MND.MND_TERMINAL_ID,
             CASE 
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '000000' THEN 'Sale'
                WHEN PTR.PTR_MSG_TYPE_ID = '0110' AND PTR.PTR_PROC_CODE = '200000' THEN 'Refund'
             END
)
SELECT 
    COALESCE(I.BUSS_DATE, N.BUSS_DATE)         AS BUSS_DATE,
    COALESCE(I.INS_CODE, N.INS_CODE)           AS INS_CODE,
    COALESCE(I.TXN_TYPE, N.TXN_TYPE)           AS TXN_TYPE,
    COALESCE(I.IPM_COUNT,0)                    AS IPM_COUNT,
    COALESCE(I.IPM_AMOUNT,0)                   AS IPM_AMOUNT,
    COALESCE(I.IPM_IRF_AMOUNT,0)               AS IPM_IRF_AMOUNT,
    COALESCE(N.INCOMING_COUNT,0)               AS INCOMING_COUNT,
    COALESCE(N.INCOMING_AMOUNT,0)              AS INCOMING_AMOUNT,
    COALESCE(N.INCOMING_IRF_AMOUNT,0)          AS INCOMING_IRF_AMOUNT,
    (COALESCE(I.IPM_COUNT,0) + COALESCE(N.INCOMING_COUNT,0)) AS TOTAL_COUNT,
    (COALESCE(I.IPM_AMOUNT,0) + COALESCE(N.INCOMING_AMOUNT,0)) AS TOTAL_AMOUNT,
    (COALESCE(I.IPM_IRF_AMOUNT,0) + COALESCE(N.INCOMING_IRF_AMOUNT,0)) AS TOTAL_IRF_AMOUNT,
    CASE 
        WHEN COALESCE(I.IPM_COUNT,0)      <> COALESCE(N.INCOMING_COUNT,0)
          OR COALESCE(I.IPM_AMOUNT,0)     <> COALESCE(N.INCOMING_AMOUNT,0)
          OR COALESCE(I.IPM_IRF_AMOUNT,0) <> COALESCE(N.INCOMING_IRF_AMOUNT,0)
        THEN 'Unmatched'
        ELSE 'Matched'
    END AS STATUS,
    NULL AS CYCLE
FROM IPM_DATA I
FULL OUTER JOIN INCOMING_DATA N
       ON I.BUSS_DATE   = N.BUSS_DATE
      AND I.INS_CODE    = N.INS_CODE
      AND I.TERMINAL_ID = N.TERMINAL_ID
      AND I.TXN_TYPE    = N.TXN_TYPE)
      GROUP BY BUSS_DATE,INS_CODE, TXN_TYPE, STATUS     
      ORDER BY BUSS_DATE ASC;
/

-- ===== VIEW VW_MC_NET_RECON_SUMMARY =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_MC_NET_RECON_SUMMARY" ("BUSINESS_DATE", "TXN_TYPE", "RRN", "TOTAL_TXN_COUNT", "TOTAL_CREDIT_AMOUNT", "TOTAL_DEBIT_AMOUNT", "TOTAL_NET_AMOUNT", "RECON_CREDIT_FEE_AMOUNT", "RECON_DEBIT_FEE_AMOUNT", "RECON_NET_FEE_AMOUNT") AS 
  SELECT 
    MFP_BUSS_DATE                         AS BUSINESS_DATE,
    'SUMMARY'                             AS TXN_TYPE,
    NULL                                  AS RRN,
    SUM(MFP_TOTAL_TXN_NUMBER)             AS TOTAL_TXN_COUNT,
    SUM(MFP_CR_RECON_AMOUNT)              AS TOTAL_CREDIT_AMOUNT,
    SUM(MFP_DR_RECON_AMOUNT)              AS TOTAL_DEBIT_AMOUNT,
    SUM(
        CASE 
            WHEN MFP_NET_TOTAL_AMOUNT_IND = 'D' THEN -MFP_NET_RECON_AMOUNT
            WHEN MFP_NET_TOTAL_AMOUNT_IND = 'C' THEN  MFP_NET_RECON_AMOUNT
            ELSE 0
        END
    )                                     AS TOTAL_NET_AMOUNT,
    SUM(MFP_CR_RECON_FEE_AMOUNT)          AS RECON_CREDIT_FEE_AMOUNT,
    SUM(MFP_DR_RECON_FEE_AMOUNT)          AS RECON_DEBIT_FEE_AMOUNT,
    SUM(
        CASE 
            WHEN MFP_NET_RECON_FEE_AMOUNT_IND = 'D' THEN -MFP_NET_RECON_FEE_AMOUNT
            WHEN MFP_NET_RECON_FEE_AMOUNT_IND = 'C' THEN  MFP_NET_RECON_FEE_AMOUNT
            ELSE 0
        END
    )      AS RECON_NET_FEE_AMOUNT
FROM 
    MC_FIN_POS_DETAILS 
GROUP BY 
    MFP_BUSS_DATE

UNION ALL

SELECT 
    BUSINESS_DATE,
    TXN_TYPE,
    RRN,
    NULL AS TOTAL_TXN_COUNT,
    SUM(TOTAL_CREDIT_AMOUNT),
    SUM(TOTAL_DEBIT_AMOUNT),
    SUM(TOTAL_CREDIT_AMOUNT - TOTAL_DEBIT_AMOUNT) AS TOTAL_NET_AMOUNT,
    NULL AS RECON_CREDIT_FEE_AMOUNT,
    NULL AS RECON_DEBIT_FEE_AMOUNT,
    NULL AS RECON_NET_FEE_AMOUNT
FROM 
    VW_MC_REPR_CHARGEBACK_REFUND_DETAILS 
GROUP BY  
BUSINESS_DATE,TXN_TYPE,RRN;
/

-- ===== VIEW VW_MC_REJECTION_DATA =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_MC_REJECTION_DATA" ("MRJ_SER_NUMBER", "MCT_TXN_TYPE", "MRJ_MSG_TYPE_ID", "MRJ_CARD_NUMBER", "MRJ_PROC_CODE", "MRJ_TXN_AMOUNT", "MCT_SCHG_AMOUNT", "MRJ_LOCAL_DATE_TIME", "MCT_EXPIRY_DATE", "MCT_POS_DATA_CODE", "MCT_FUNC_CODE", "MCT_MSG_REASON_CODE", "MCT_MCC", "MRJ_ACQ_REF_NUMBER", "MRJ_ACQ_INST_ID_CODE", "MRJ_RET_REF_NUMBER", "MRJ_APPR_CODE", "MRJ_RESP_CODE", "MCT_SERVICE_CODE", "MCT_TERMINAL_ID", "MCT_MERCHANT_ID", "MCT_ME_NAME", "MCT_ME_CITY", "MCT_ME_ZIP_CODE", "MCT_ME_COUNTRY", "MCT_TRL_TYPE", "MRJ_MOTO_ECOM_INDICATOR", "MRJ_TXN_FEE_AMOUNT", "MCT_TXN_CURR_EXP", "MCT_TXN_CUR_CODE", "MCT_IRD", "MRJ_SETL_FLAG", "MCT_CARD_SEQ_NUMBER", "MCT_APP_CRYPTOGRAM", "MCT_CRYPT_INFO_DATA", "MCT_ISS_APP_DATA", "MCT_UPBL_NUMBER", "MCT_APP_TXN_COUNTER", "MCT_TRL_VER_RESULTS", "MCT_TXN_DATE", "MCT_CHIP_TXN_DATE", "MCT_CHIP_TXN_TYPE", "MCT_CRYPT_AMOUNT", "MCT_APP_IC_PROFILE", "MCT_TRL_CON_CODE", "MCT_CASHBACK_AMOUNT", "MCT_CVM_RESULTS", "MCT_TRL_CAPABILITIES", "MCT_TCC", "MCT_CHIP_CUR_CODE", "MCT_CHIP_TRL_TYPE", "MCT_TRL_APP_VER_NUMBER", "MCT_TXN_SEQ_COUNTER", "MCT_ISS_AUTH_DATA", "MCT_TXN_LIFE_CYCL_ID", "MCT_MSG_NUMBER", "MCT_MEMBER_TEXT", "MCT_ORG_INST_ID_CODE", "MRJ_REV_INDICATOR", "MCT_MER_MC_ASSIGNED_ID", "MRJ_CARD_TYPE", "MCT_DOM_INTL_FLAG", "MCT_SMS_DMS_FLAG", "MCT_POS_PG_TYPE", "MRJ_CENTRE_PROC_DATE", "MCT_OUT_FILE_DATE", "MRJ_REJECT_FIELD", "MCT_ENC_CARD_NUMBER", "MCT_ME_COUNTRY_OF_ORIGIN") AS 
  SELECT 

MRJ.MRJ_SER_NUMBER
, MCT.MCT_TXN_TYPE	
, MRJ.MRJ_MSG_TYPE_ID
, MRJ.MRJ_CARD_NUMBER
, MRJ.MRJ_PROC_CODE
, MRJ.MRJ_TXN_AMOUNT
, MCT.MCT_SCHG_AMOUNT
, MRJ.MRJ_LOCAL_DATE_TIME
, MCT.MCT_EXPIRY_DATE
, MCT.MCT_POS_DATA_CODE
, MCT.MCT_FUNC_CODE
, MCT.MCT_MSG_REASON_CODE
, MCT.MCT_MCC
, MRJ.MRJ_ACQ_REF_NUMBER
, MRJ.MRJ_ACQ_INST_ID_CODE
, MRJ.MRJ_RET_REF_NUMBER
, MRJ.MRJ_APPR_CODE
, MRJ.MRJ_RESP_CODE
, MCT.MCT_SERVICE_CODE
, MCT.MCT_TERMINAL_ID
, MCT.MCT_MERCHANT_ID
, MCT.MCT_ME_NAME 
, MCT.MCT_ME_CITY 
, MCT.MCT_ME_ZIP_CODE
, MCT.MCT_ME_COUNTRY 
, MCT.MCT_TRL_TYPE
, MRJ.MRJ_MOTO_ECOM_INDICATOR 
, MRJ.MRJ_TXN_FEE_AMOUNT
, MCT.MCT_TXN_CURR_EXP 
, MCT.MCT_TXN_CUR_CODE 
, MCT.MCT_IRD
, MRJ.MRJ_SETL_FLAG
, MCT.MCT_CARD_SEQ_NUMBER
, MCT.MCT_APP_CRYPTOGRAM
, MCT.MCT_CRYPT_INFO_DATA
, MCT.MCT_ISS_APP_DATA
, MCT.MCT_UPBL_NUMBER
, MCT.MCT_APP_TXN_COUNTER

, MCT.MCT_TRL_VER_RESULTS
, MCT.MCT_TXN_DATE
, MCT.MCT_CHIP_TXN_DATE
, MCT.MCT_CHIP_TXN_TYPE
, MCT.MCT_CRYPT_AMOUNT
, MCT.MCT_APP_IC_PROFILE
, MCT.MCT_TRL_CON_CODE
, MCT.MCT_CASHBACK_AMOUNT
, MCT.MCT_CVM_RESULTS
, MCT.MCT_TRL_CAPABILITIES
, MCT.MCT_TCC
, MCT.MCT_CHIP_CUR_CODE
, MCT.MCT_CHIP_TRL_TYPE
, MCT.MCT_TRL_APP_VER_NUMBER
, MCT.MCT_TXN_SEQ_COUNTER
, MCT.MCT_ISS_AUTH_DATA
, MCT.MCT_TXN_LIFE_CYCL_ID
, MCT.MCT_MSG_NUMBER
, MCT.MCT_MEMBER_TEXT
, MCT.MCT_ORG_INST_ID_CODE
, MRJ.MRJ_REV_INDICATOR
, MCT.MCT_MER_MC_ASSIGNED_ID
, MRJ.MRJ_CARD_TYPE
, MCT.MCT_DOM_INTL_FLAG
, MCT.MCT_SMS_DMS_FLAG
, MCT.MCT_POS_PG_TYPE
, MRJ.MRJ_CENTRE_PROC_DATE
, MCT.MCT_OUT_FILE_DATE
, MRJ.MRJ_REJECT_FIELD
, MCT.MCT_ENC_CARD_NUMBER
, MCT.MCT_ME_COUNTRY_OF_ORIGIN

FROM MC_REJECTIONS MRJ 
JOIN MC_ACQ_TXN_DATA MCT ON 
MRJ.MRJ_RET_REF_NUMBER = MCT.MCT_RET_REF_NUMBER 
AND MRJ.MRJ_MSG_TYPE_ID = MCT.MCT_MSG_TYPE_ID
AND MCT.MCT_PROC_CODE = MRJ.MRJ_PROC_CODE
WHERE MCT.MCT_GEN_STATUS <> 7 AND MRJ.MRJ_GEN_STATUS <>0;
/

-- ===== VIEW VW_MC_REPR_CHARGEBACK_REFUND_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_MC_REPR_CHARGEBACK_REFUND_DETAILS" ("BUSINESS_DATE", "RRN", "TXN_TYPE", "TOTAL_CREDIT_AMOUNT", "TOTAL_DEBIT_AMOUNT") AS 
  SELECT 
    BUSINESS_DATE,
    RRN,
    TXN_TYPE,
    CREDIT_AMOUNT AS TOTAL_CREDIT_AMOUNT,
    DEBIT_AMOUNT  AS TOTAL_DEBIT_AMOUNT
FROM (
    -- Presentment: Credit
    SELECT 
        MRP_BUSS_DATE AS BUSINESS_DATE,
        MRP_RET_REF_NUMBER AS RRN,
        'PRESENTMENT' AS TXN_TYPE,
        MRP_TXN_AMOUNT AS CREDIT_AMOUNT,
        0 AS DEBIT_AMOUNT
    FROM 
        MC_REPR_GENERATED

    UNION ALL

    -- ChargeBack: Debit
    SELECT 
        MAX_BUSS_DATE AS BUSINESS_DATE,
        MAX_RET_REF_NUMBER AS RRN,
        'CHARGEBACK' AS TXN_TYPE,
        0 AS CREDIT_AMOUNT,
        MAX_TXN_AMOUNT AS DEBIT_AMOUNT
    FROM 
        MC_ACQ_EXCEPTIONS
    WHERE 
        MAX_MESG_TYPE_ID = 1442

    UNION ALL

    -- Refund: Credit (Proc Code = 19)
    SELECT 
        MCF_BUSS_DATE AS BUSINESS_DATE,
        MCT_RET_REF_NUMBER AS RRN,
        'REFUND' AS TXN_TYPE,
        MCF_TXN_AMOUNT AS CREDIT_AMOUNT,
        0 AS DEBIT_AMOUNT
    FROM 
         MC_IPM_FEES JOIN MC_ACQ_TXN_DATA ON MCT_ACQ_REF_DATA = MCF_ACQ_REF_DATA
    WHERE 
        MCF_PROC_CODE = 19

    UNION ALL

    -- Fee: Debit (Proc Code = 29)
    SELECT 
        MCF_BUSS_DATE AS BUSINESS_DATE,
        MCT_RET_REF_NUMBER AS RRN,
        'FEE' AS TXN_TYPE,
        0 AS CREDIT_AMOUNT,
        MCF_TXN_AMOUNT AS DEBIT_AMOUNT
    FROM 
         MC_IPM_FEES JOIN MC_ACQ_TXN_DATA ON MCT_ACQ_REF_DATA = MCF_ACQ_REF_DATA
    WHERE 
        MCF_PROC_CODE = 29
) unified_data;
/

-- ===== VIEW VW_MC_REPR_CHARGEBACK_RETREVAL_REJ_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_MC_REPR_CHARGEBACK_RETREVAL_REJ_DETAILS" ("TXN_TYPE", "INS_CODE", "CARD_NUMBER", "RRN", "BUSS_DATE", "AMOUNT", "IRF_AMOUNT") AS 
  SELECT 
		'CHARGEBACK' AS TXN_TYPE,
        MAX_INS_CODE AS INS_CODE,
        MAX_CARD_NUMBER AS CARD_NUMBER,
        MAX_RET_REF_NUMBER AS RRN,
        MAX_BUSS_DATE AS BUSS_DATE,
        MAX_TXN_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        MC_ACQ_EXCEPTIONS 
		LEFT JOIN POS_TRANSACTIONS ON PTR_RET_REF_NUMBER = MAX_RET_REF_NUMBER
    WHERE 
        MAX_MESG_TYPE_ID = 1442
		
 UNION ALL
 
 SELECT 
       'RETREVIAL REQUEST' AS TXN_TYPE,
        MAX_INS_CODE AS INS_CODE,
        MAX_CARD_NUMBER AS CARD_NUMBER,
        MAX_RET_REF_NUMBER AS RRN,
        MAX_BUSS_DATE AS BUSS_DATE,
        MAX_TXN_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        MC_ACQ_EXCEPTIONS 
        LEFT JOIN POS_TRANSACTIONS ON PTR_RET_REF_NUMBER = MAX_RET_REF_NUMBER
		WHERE MAX_FUNC_CODE=603 AND MAX_MESG_TYPE_ID = 1644
		
 UNION ALL
		
SELECT 
       'REJECTION' AS TXN_TYPE,
        MRJ_INS_CODE AS INS_CODE,
        MRJ_CARD_NUMBER AS CARD_NUMBER,
        MRJ_RET_REF_NUMBER AS RRN,
        MRJ_BUSS_DATE AS BUSS_DATE,
        MRJ_TXN_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        MC_REJECTIONS 
        LEFT JOIN POS_TRANSACTIONS ON PTR_RET_REF_NUMBER = MRJ_RET_REF_NUMBER
		
 UNION ALL
		
SELECT 
       'PRESENTMENT' AS TXN_TYPE,
        MRP_INS_CODE AS INS_CODE,
        MRP_CARD_NUMBER AS CARD_NUMBER,
        MRP_RET_REF_NUMBER AS RRN,
        MRP_BUSS_DATE AS BUSS_DATE,
        MRP_TXN_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        MC_REPR_GENERATED 
        LEFT JOIN POS_TRANSACTIONS ON PTR_RET_REF_NUMBER = MRP_RET_REF_NUMBER;
/

-- ===== VIEW VW_OMANNET_TXN_REPORT =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_OMANNET_TXN_REPORT" ("PTR_SER_NUMBER", "PTR_INS_CODE", "PTR_INT_CODE", "PTR_BUSS_DATE", "PTR_TXN_CODE", "PTR_TXN_DATE_TIME", "PTR_MERCHANT_ID", "CBO_CARD_ACC_TID", "CBO_TXN_AMOUNT", "CBO_TXN_TYPE", "PTR_MSG_TYPE_ID", "PTR_RESP_CODE", "PTR_CARD_NUMBER", "PTR_CARD_TYPE", "PTR_NETWORK", "CBO_RET_REF_NUMBER", "PTR_CARD_DOM_INTL_FLAG", "PTR_MCC", "CBO_APPROVAL_CODE", "PTR_POS_ENTRY_MODE", "CBO_INTERCHANGE_FEE", "CBO_TPS_MATCH", "CBO_POS_MATCH", "CBO_MATCH_FLAG", "RECON_MATCHED") AS 
  SELECT
	p.PTR_SER_NUMBER,
	P.PTR_INS_CODE,
    p.PTR_INT_CODE,
    P.PTR_BUSS_DATE,
	P.PTR_TXN_CODE,
	P.PTR_TXN_DATE_TIME,
    P.PTR_MERCHANT_ID,
    C.CBO_CARD_ACC_TID,
    C.CBO_TXN_AMOUNT,
    C.CBO_TXN_TYPE,
    p.PTR_MSG_TYPE_ID,
    CASE WHEN P.PTR_RESP_CODE = '00' THEN 'Success'
         ELSE 'Failed' END AS PTR_RESP_CODE,
    P.PTR_CARD_NUMBER,
    P.PTR_CARD_TYPE,
    CASE WHEN P.PTR_NETWORK = 'OMANNET' THEN 'OmanNet'
         ELSE P.PTR_NETWORK END AS PTR_NETWORK,   
    C.CBO_RET_REF_NUMBER,
    P.PTR_CARD_DOM_INTL_FLAG,
    P.PTR_MCC,
    C.CBO_APPROVAL_CODE,
    P.PTR_POS_ENTRY_MODE,
    C.CBO_INTERCHANGE_FEE,
    CASE WHEN C.CBO_TPS_MATCH_STATUS = 'M' THEN 'Success'
         ELSE 'Failed' END AS CBO_TPS_MATCH,
    CASE WHEN C.CBO_POS_MATCH_STATUS = 'M' THEN 'Success'
         ELSE 'Failed' END AS CBO_POS_MATCH,
    CASE WHEN C.CBO_MATCH_STATUS = 'M' THEN 'Success'
         ELSE 'Failed' END AS CBO_MATCH_FLAG,
    CASE WHEN C.CBO_MATCH_STATUS = 'M' THEN 'Matched' 
		 ELSE 'Unmatched' END AS RECON_MATCHED

FROM CBO_TRANSACTIONS_DATA C
LEFT JOIN POS_TRANSACTIONS P ON P.PTR_RET_REF_NUMBER = C.CBO_RET_REF_NUMBER 
   AND P.PTR_APPR_CODE = CBO_APPROVAL_CODE 
WHERE P.PTR_GEN_STATUS !=7;
/

-- ===== VIEW VW_OUTGOING_TXN_REPORT =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_OUTGOING_TXN_REPORT" ("PTR_SER_NUMBER", "PTR_INS_CODE", "PTR_INT_CODE", "PTR_BUSS_DATE", "PTR_TXN_DATE_TIME", "PTR_TXN_CUR_CODE", "PTR_TXN_CODE", "PTR_MSG_TYPE_ID", "PTR_RET_REF_NUMBER", "PTR_NETWORK", "MERCHANT_ID", "TERMINAL_ID", "TXN_AMOUNT", "TXN_TYPE", "CARD_TYPE", "RET_REF_NUMBER", "CARD_DOM_INTL_FLAG", "PTR_CARD_NUMBER", "PTR_IRF_FIXED", "PTR_IRF_PERCENT", "PTR_IRF_AMOUNT", "PTR_IRF_AMOUNT_USD", "PTR_IRD") AS 
  SELECT
	p.PTR_SER_NUMBER,
	P.PTR_INS_CODE,
    p.PTR_INT_CODE,
    P.PTR_BUSS_DATE,
	P.PTR_TXN_DATE_TIME,
	p.PTR_TXN_CUR_CODE,
    p.PTR_TXN_CODE,
    p.PTR_MSG_TYPE_ID,
	P.PTR_RET_REF_NUMBER,
	P.PTR_NETWORK,
    COALESCE(V.VTD_MERCHANT_ID, M.MCT_MERCHANT_ID, J.JWN_MERCHANT_ID, A.ATD_MERCHANT_ID, G.MGD_MERCHANT_ID, GOC.GOC_MERCHANT_ID) AS MERCHANT_ID,
    COALESCE(V.VTD_TERMINAL_ID, M.MCT_TERMINAL_ID, J.JWN_TERMINAL_ID, A.ATD_TERMINAL_ID, G.MGD_TERMINAL_ID, GOC.GOC_TERMINAL_ID) AS TERMINAL_ID,
    COALESCE(V.VTD_TXN_AMOUNT,  M.MCT_TXN_AMOUNT,  J.JWN_TXN_AMOUNT,  A.ATD_TXN_AMOUNT,  G.MGD_TXN_AMOUNT, 	GOC.GOC_TXN_AMOUNT)  AS TXN_AMOUNT,
    COALESCE(V.VTD_TXN_TYPE,    M.MCT_TXN_TYPE,    J.JWN_TXN_TYPE,    A.ATD_TXN_TYPE,	 G.MGD_TXN_TYPE, 	GOC.GOC_TXN_TYPE)    AS TXN_TYPE,
    COALESCE(V.VTD_CARD_TYPE,   M.MCT_CARD_TYPE,   J.JWN_CARD_TYPE,   A.ATD_CARD_TYPE, 	 G.MGD_CARD_TYPE, 	GOC.GOC_CARD_TYPE)   AS CARD_TYPE,
    COALESCE(V.VTD_RET_REF_NUMBER, M.MCT_RET_REF_NUMBER, J.JWN_RET_REF_NUMBER, A.ATD_RET_REF_NUMBER, G.MGD_RET_REF_NUMBER, 	   GOC.GOC_RET_REF_NUMBER) AS RET_REF_NUMBER,
    COALESCE(V.VTD_DOM_INTL_FLAG,  M.MCT_DOM_INTL_FLAG,  J.JWN_DOM_INTL_FLAG,  A.ATD_DOM_INTL_FLAG , G.MGD_CARD_DOM_INTL_FLAG, GOC.GOC_DOM_INTL_FLAG)  AS CARD_DOM_INTL_FLAG,
    P.PTR_CARD_NUMBER,
    P.PTR_IRF_FIXED,
    P.PTR_IRF_PERCENT,
    P.PTR_IRF_AMOUNT,
    P.PTR_IRF_AMOUNT_USD,
    P.PTR_IRD
FROM POS_TRANSACTIONS P
LEFT JOIN VISA_ACQ_TXN_DATA     V ON V.VTD_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
LEFT JOIN MC_ACQ_TXN_DATA       M ON M.MCT_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
LEFT JOIN JAYWAN_ACQ_TXN_DATA   J ON J.JWN_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
LEFT JOIN AMEX_ACQ_TXN_DATA     A ON A.ATD_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
LEFT JOIN MC_GCO_DATA G ON G.MGD_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
LEFT JOIN VISA_GOC_DATA GOC ON GOC.GOC_RET_REF_NUMBER = P.PTR_RET_REF_NUMBER
WHERE P.PTR_OUT_STATUS='Completed'
AND P.PTR_GEN_STATUS !=7;
/

-- ===== VIEW VW_TXN_INQUIRY_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_TXN_INQUIRY_DETAILS" ("PTR_SER_NUMBER", "PTR_MERCHANT_ID", "PTR_TERMINAL_ID", "PTR_RET_REF_NUMBER", "PTR_IRD", "PTR_IRF_FIXED", "PTR_IRF_PERCENT", "PTR_IRF_AMOUNT", "PTR_IRF_MIN_AMOUNT", "PTR_IRF_MAX_AMOUNT", "PTR_TXN_AMOUNT", "PTR_CARD_DOM_INTL_FLAG", "PTR_CARD_TYPE", "PTR_CARD_NUMBER", "PTR_TXN_TYPE", "PTR_TXN_CODE", "PTR_REMARKS", "PTR_NETWORK", "PTR_TXN_DATE_TIME", "PTR_RESP_CODE", "PTR_OUT_STATUS", "PTR_INC_STATUS", "PTR_MSG_TYPE_ID", "PTR_BANK_CODE", "PTR_REV_INDICATOR", "PTR_IRF_AMOUNT_USD", "PTR_ORG_RRN", "PTR_LOCAL_DATE_TIME", "PTR_TXN_ID", "PTR_NETWORK_DATA", "PTR_PROC_CODE", "PTR_SCHEME", "PTR_DCC_INDICATOR", "PTR_DCC_AMOUNT", "PTR_DCC_CURRENCY", "PTR_DCC_EXCHANGE_RATE", "VND_INCHG_FEE_AMOUNT", "VND_INCHG_FEE_SIGN", "VND_FEE_DESC", "VND_IRF_MATCH", "VND_IRF_DIFF", "VND_TXN_AMOUNT", "MND_TXN_AMOUNT", "MND_RECON_AMOUNT", "MND_TXN_IRF_AMOUNT", "MND_TXN_IRF_USD_AMOUNT", "MND_IRD", "MND_IRF_MATCH", "MND_IRF_DIFF", "MND_BUSINESS_CYCLE", "MND_FILE_ID", "MND_APPROVAL_CODE", "USN_IRF", "USN_PF1", "USN_PF2", "NWD_TXN_ID", "NWD_INCHG_FEE", "NWD_INCHG_FEE_SIGN", "NWD_IRF_MATCH", "NWD_IRF_DIFF") AS 
  SELECT 
    p.PTR_SER_NUMBER, 
    P.PTR_MERCHANT_ID,
    P.PTR_TERMINAL_ID,
    P.PTR_RET_REF_NUMBER,
    P.PTR_IRD,
    P.PTR_IRF_FIXED,
    P.PTR_IRF_PERCENT,
	P.PTR_IRF_AMOUNT,
    P.PTR_IRF_MIN_AMOUNT,
    P.PTR_IRF_MAX_AMOUNT,
    P.PTR_TXN_AMOUNT,
    P.PTR_CARD_DOM_INTL_FLAG,
    P.PTR_CARD_TYPE,			
    P.PTR_CARD_NUMBER,
    P.PTR_TXN_TYPE,
    p.PTR_TXN_CODE,
    P.PTR_REMARKS,
    P.PTR_NETWORK,
    P.PTR_TXN_DATE_TIME,
    P.PTR_RESP_CODE,
    P.PTR_OUT_STATUS,
    P.PTR_INC_STATUS,
    P.PTR_MSG_TYPE_ID,
    P.PTR_BANK_CODE,
    P.PTR_REV_INDICATOR,
    P.PTR_IRF_AMOUNT_USD,
    P.PTR_ORG_RRN,
    P.PTR_LOCAL_DATE_TIME,
    P.PTR_TXN_ID,
    TRIM(P.PTR_NETWORK_DATA) AS PTR_NETWORK_DATA,
	P.PTR_PROC_CODE,
	p.PTR_SCHEME,
	p.PTR_DCC_INDICATOR,
    P.PTR_DCC_AMOUNT,
    P.PTR_DCC_CURRENCY,
    P.PTR_DCC_EXCHANGE_RATE,
	
    -- VISA network 
    CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_INCHG_FEE_AMOUNT ELSE NULL END AS VND_INCHG_FEE_AMOUNT,
    CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_INCHG_FEE_SIGN ELSE NULL END AS VND_INCHG_FEE_SIGN,
    CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_FEE_DESC ELSE NULL END AS VND_FEE_DESC,
    CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_IRF_MATCH ELSE NULL END AS VND_IRF_MATCH,
    CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_IRF_DIFF ELSE NULL END AS VND_IRF_DIFF,
	CASE WHEN P.PTR_NETWORK = 'VISA' THEN V.VND_TXN_AMOUNT ELSE NULL END AS VND_TXN_AMOUNT,
    
    -- MCI network 
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_TXN_AMOUNT ELSE NULL END AS MND_TXN_AMOUNT,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_RECON_AMOUNT ELSE NULL END AS MND_RECON_AMOUNT,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_IRF_AMOUNT ELSE NULL END AS MND_TXN_IRF_AMOUNT,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_IRF_AMOUNT_USD ELSE NULL END AS MND_TXN_IRF_USD_AMOUNT,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_IRD ELSE NULL END AS MND_IRD,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_IRF_MATCH ELSE NULL END AS MND_IRF_MATCH,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_IRF_DIFF ELSE NULL END AS MND_IRF_DIFF,
	CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_BUSINESS_CYCLE ELSE NULL END AS MND_BUSINESS_CYCLE,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_FILE_ID ELSE NULL END AS MND_FILE_ID,
    CASE WHEN P.PTR_NETWORK = 'MCI' THEN M.MND_APPROVAL_CODE ELSE NULL END AS MND_APPROVAL_CODE,
    
    -- UAESWITCH
     CASE WHEN P.PTR_NETWORK = 'UAESWITCH' THEN U.USN_IRF ELSE NULL END AS USN_IRF,
     CASE WHEN P.PTR_NETWORK = 'UAESWITCH' THEN U.USN_PF1 ELSE NULL END AS USN_PF1,
     CASE WHEN P.PTR_NETWORK = 'UAESWITCH' THEN U.USN_PF2 ELSE NULL END AS USN_PF2,
	 
	  -- VSMS network 
    CASE WHEN P.PTR_NETWORK = 'VSMS' THEN N.NWD_TXN_ID ELSE NULL END AS NWD_TXN_ID,
    CASE WHEN P.PTR_NETWORK = 'VSMS' THEN N.NWD_INCHG_FEE ELSE NULL END AS NWD_INCHG_FEE,
    CASE WHEN P.PTR_NETWORK = 'VSMS' THEN N.NWD_INCHG_FEE_SIGN ELSE NULL END AS NWD_INCHG_FEE_SIGN,
    CASE WHEN P.PTR_NETWORK = 'VSMS' THEN N.NWD_IRF_MATCH ELSE NULL END AS NWD_IRF_MATCH,
    CASE WHEN P.PTR_NETWORK = 'VSMS' THEN N.NWD_IRF_DIFF ELSE NULL END AS NWD_IRF_DIFF

FROM POS_TRANSACTIONS P

LEFT JOIN UAE_SWITCH_NETWORK_DATA U
    ON U.USN_AUTH_ID_RESPONSE = P.PTR_APPR_CODE
	AND U.USN_RETRIEVAL_REF_NO = P.PTR_RET_REF_NUMBER
	
LEFT JOIN VISA_NETWORK_DATA V 
    ON V.VND_TXN_ID = P.PTR_TXN_ID
	
LEFT JOIN MC_NETWORK_DATA M 
     ON TRIM(M.MND_TRACE_ID) = TRIM(P.PTR_NETWORK_DATA)
	 
LEFT JOIN NETWORK_DATA N
    ON N.NWD_APPR_CODE = P.PTR_APPR_CODE 
    AND N.NWD_RET_REF_NUMBER=P.PTR_RET_REF_NUMBER
	
WHERE COALESCE (V.VND_ORIGIN_ID ,'O')='O' 
AND COALESCE(V.VND_USAGE_CODE,'1')='1';
/

-- ===== VIEW VW_VISA_FUNDS_TRANSFER_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_VISA_FUNDS_TRANSFER_DETAILS" ("BUSINESS_DATE", "FUND_TRANSFER_CREDIT", "TXN_COUNT", "TXN_CREDIT", "TXN_DEBIT", "TOTAL_TXN", "REIMBURSEMNET_CREDIT", "REIMBURSEMNET_DEBIT", "REIMBURSEMNET_TOTAL") AS 
  SELECT 
    VSE_BUSS_DATE AS BUSINESS_DATE,

    -- Funds Transfer Amount
    SUM(CASE WHEN VSE_RECORD_TYPE = 'T' THEN VSE_TOTAL_AMOUNT END) AS FUND_TRANSFER_CREDIT,

    -- Total Transaction Details
    SUM(CASE WHEN VSE_RECORD_TYPE = 'I' THEN VSE_COUNT        END) AS TXN_COUNT,
    SUM(CASE WHEN VSE_RECORD_TYPE = 'I' THEN VSE_CR_AMOUNT    END) AS TXN_CREDIT,
    SUM(CASE WHEN VSE_RECORD_TYPE = 'I' THEN VSE_DR_AMOUNT    END) AS TXN_DEBIT,
    SUM(CASE WHEN VSE_RECORD_TYPE = 'I' AND VSE_TOTAL_AMOUNT_IND = 'DB' 
             THEN -VSE_TOTAL_AMOUNT
             WHEN VSE_RECORD_TYPE = 'I' AND VSE_TOTAL_AMOUNT_IND = 'CR' 
             THEN  VSE_TOTAL_AMOUNT ELSE 0 END) AS TOTAL_TXN,

    -- Reimbursement Fees
    SUM(CASE WHEN VSE_RECORD_TYPE = 'F' THEN VSE_CR_AMOUNT    END) AS REIMBURSEMNET_CREDIT,
    SUM(CASE WHEN VSE_RECORD_TYPE = 'F' THEN VSE_DR_AMOUNT    END) AS REIMBURSEMNET_DEBIT,
    SUM(CASE WHEN VSE_RECORD_TYPE = 'F' AND VSE_TOTAL_AMOUNT_IND = 'DB' 
             THEN -VSE_TOTAL_AMOUNT
             WHEN VSE_RECORD_TYPE = 'F' AND VSE_TOTAL_AMOUNT_IND = 'CR' 
             THEN  VSE_TOTAL_AMOUNT ELSE 0 END) AS REIMBURSEMNET_TOTAL

FROM VISA_SETTLEMENTS
WHERE VSE_BUSS_MODE = '9' 
GROUP BY VSE_BUSS_DATE;
/

-- ===== VIEW VW_VISA_REPR_CHARGEBACK_RETREVAL_REJ_DETAILS =====

  CREATE OR REPLACE EDITIONABLE VIEW "NETWORK_SETTLEMENT_UAT"."VW_VISA_REPR_CHARGEBACK_RETREVAL_REJ_DETAILS" ("SER_NUMBER", "TXN_TYPE", "INS_CODE", "CARD_NUMBER", "RRN", "TID", "BUSS_DATE", "AMOUNT", "IRF_AMOUNT") AS 
  SELECT ROW_NUMBER() OVER (ORDER BY 1) AS SER_NUMBER,t."TXN_TYPE",t."INS_CODE",t."CARD_NUMBER",t."RRN",t."TID",t."BUSS_DATE",t."AMOUNT",t."IRF_AMOUNT"
FROM (
 SELECT 
		'CHARGEBACK' AS TXN_TYPE,
        CBR_INS_CODE AS INS_CODE,
        CBR_CARD_NUMBER AS CARD_NUMBER,
        PTR_RET_REF_NUMBER AS RRN,
		CBR_TERMINAL_ID AS TID,
        CBR_BUSS_DATE AS BUSS_DATE,
        CBR_SRC_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        VISA_CB_RECEIVED 
		LEFT JOIN POS_TRANSACTIONS ON PTR_TXN_ID = CBR_TXN_ID
		
 UNION ALL
 
  SELECT 
       'RETREVIAL REQUEST' AS TXN_TYPE,
        RRR_INS_CODE AS INS_CODE,
        RRR_CARD_NUMBER AS CARD_NUMBER,
        PTR_RET_REF_NUMBER AS RRN,
        PTR_TERMINAL_ID AS TID,
        RRR_BUSS_DATE AS BUSS_DATE,
        RRR_TXN_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        VISA_RR_RECEIVED 
        LEFT JOIN POS_TRANSACTIONS ON PTR_TXN_ID = RRR_TXN_ID
	
		
 UNION ALL	
		
SELECT 
       'PRESENTMENT' AS TXN_TYPE,
        PRR_INS_CODE AS INS_CODE,
        PRR_CARD_NUMBER AS CARD_NUMBER,
        PTR_RET_REF_NUMBER AS RRN,
        PRR_TERMINAL_ID AS TID,
        PRR_BUSS_DATE AS BUSS_DATE,
        PRR_SRC_AMOUNT AS AMOUNT,
        PTR_IRF_AMOUNT AS IRF_AMOUNT
    FROM 
        VISA_PR_RECEIVED 
        LEFT JOIN POS_TRANSACTIONS ON PTR_TXN_ID = PRR_TXN_ID
)t;
/

-- ===== FUNCTION FN_SPLITSTRING =====

  CREATE OR REPLACE EDITIONABLE FUNCTION "NETWORK_SETTLEMENT_UAT"."FN_SPLITSTRING" (INPUT_ IN NCLOB)
	RETURN ITEM PIPELINED IS
	StartIndex INTEGER :=0;EndIndex INTEGER :=0;Character_ CHAR(1):=','; InputString NVARCHAR2(4000); OutputString NVARCHAR2(1000);
	TrimString NVARCHAR2(4000);
BEGIN

	StartIndex:=1;
	IF SUBSTR(INPUT_,LENGTH(INPUT_),LENGTH(INPUT_)) <> Character_ THEN
        InputString:=CONCAT(INPUT_,Character_);
	END IF;

	WHILE EndIndex <= LENGTH(InputString) LOOP
         EndIndex := INSTR(InputString,Character_);
		TrimString := REPLACE(LTRIM(RTRIM(SUBSTR(InputString,StartIndex,EndIndex-1))),CHR(13),CHR(10));
		OutputString:=REPLACE(TrimString,CHR(10),'');
		PIPE ROW(SPLIT_TABLE(OutputString));
		InputString := SUBSTR(InputString, EndIndex + 1, LENGTH(InputString));
        EndIndex := INSTR(InputString,Character_);
	END LOOP;
END fn_SplitString;
/

-- ===== TYPE ITEM =====

  CREATE OR REPLACE EDITIONABLE TYPE "NETWORK_SETTLEMENT_UAT"."ITEM" AS TABLE OF SPLIT_TABLE

/

-- ===== TYPE SPLIT_TABLE =====

  CREATE OR REPLACE EDITIONABLE TYPE "NETWORK_SETTLEMENT_UAT"."SPLIT_TABLE" AS OBJECT (
    SPLIT_TABLE NVARCHAR2(1000)
)

/
